import unittest

class Test(unittest.TestCase):
    def test_gcd(self):
        self.assertEqual(gcd(48, 18), 6)
        self.assertEqual(gcd(17, 5), 1)
    def test_lcm(self):
        self.assertEqual(lcm(4, 6), 12)
        self.assertEqual(lcm(21, 6), 42)
    def test_gcd_equal(self):
        self.assertEqual(gcd(10, 10), 10)

